package glitch

import data.glitch_lib

# Sensitive credential field name patterns
credential_fields := {
    "password", "secret", "token", "key", "credential", "auth_token",
    "access_key", "secret_key", "api_key", "private_key", "certificate",
    "passphrase", "root_password", "admin_password", "connection_string",
    "dsn", "uri", "url", "default_user", "default_username", "admin_user",
    "root_user", "service_account", "stringdata"
}

# Placeholder patterns indicating hard-coded default/test credentials
placeholder_patterns := {"changeme", "password123", "admin", "default", "secret", "test", "demo"}

# Check if field name indicates a credential field
is_credential_field(name) {
    lower_name := lower(name)
    contains(lower_name, credential_fields[_])
}

# Check for placeholder/default credential values
is_placeholder_value(value) {
    lower_val := lower(value)
    lower_val == placeholder_patterns[_]
}

# Check if string contains potential encoded secret (base64/hex patterns)
is_encoded_pattern(value) {
    regex.match(`^(?:[A-Za-z0-9+/]{20,}={0,2})$`, value)
} else {
    regex.match(`^[a-fA-F0-9]{16,}$`, value)
}

# Check if value is a hard-coded literal (String) and not a secure reference
is_hardcoded_literal(value) {
    value.ir_type == "String"
    not is_secure_reference(value.value)
}

# Check for secure reference patterns (negative indicators - these are safe)
is_secure_reference(str) {
    regex.match(`\$\{`, str)
} else {
    regex.match(`\$[A-Z_]`, str)
} else {
    regex.match(`(?i)(?:data|var|vault|secrets?|kms|key_vault)`, str)
} else {
    regex.match(`(?i)(?:file\(|templatefile\(|random_)`, str)
}

# Recursively check nested structures for hard-coded credentials
has_hardcoded_credential(value) {
    # Direct string value
    value.ir_type == "String"
    value.value != ""
    not is_secure_reference(value.value)
} else {
    # Nested hash
    value.ir_type == "Hash"
    value.value[_].value != null
    has_hardcoded_credential(value.value[_].value)
} else {
    # Nested array
    value.ir_type == "Array"
    value.value[_] != null
    has_hardcoded_credential(value.value[_])
}

# Check if value contains suspicious credential content
has_suspicious_credential_content(value) {
    value.ir_type == "String"
    val := lower(value.value)
    count(val) > 3
    is_placeholder_value(val)
} else {
    value.ir_type == "String"
    val := value.value
    count(val) > 8
    is_encoded_pattern(val)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_credential_field(attr.name)
    has_hardcoded_credential(attr.value)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of Hard-coded Credentials - Avoid hard-coding credentials in Infrastructure as Code. Use secret management systems instead. (CWE-798)"
    }
}

